mapper.select:
WITH rms AS MATERIALIZED (
SELECT DISTINCT ON (pp.played_at, pp.replay_id) pp.replay_id AS rid, pp.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match_participant pp INNER JOIN public.rta_match m ON m.replay_id = pp.replay_id WHERE pp.season_id = #{seasonId} AND pp.rating_id = #{ratingId} ORDER BY pp.played_at DESC NULLS LAST, pp.replay_id DESC LIMIT #{limit} OFFSET #{offset}
SELECT DISTINCT ON (pp.played_at, pp.replay_id) pp.replay_id AS rid, pp.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match_participant pp INNER JOIN public.rta_match m ON m.replay_id = pp.replay_id WHERE pp.season_id = #{seasonId} AND pp.rating_id IN #{rid} ORDER BY pp.played_at DESC NULLS LAST, pp.replay_id DESC LIMIT #{limit} OFFSET #{offset}
SELECT m.replay_id AS rid, m.played_at AS date_add, m.battle_type, m.winner_wizard_id AS winner_wizard_id FROM public.rta_match m WHERE 1 = 1
ORDER BY m.played_at DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}
), banned_pick AS ( SELECT ub.replay_id, ub.wizard_id AS wizard_id, MIN(ub.unit_master_id::text) AS banned_unit FROM public.rta_match_unit_pick ub INNER JOIN rms ON rms.rid = ub.replay_id WHERE ub.is_banned = true GROUP BY ub.replay_id, ub.wizard_id ), user_info AS ( SELECT p.replay_id, p.wizard_id AS wizard_id, p.wizard_name, p.channel_uid, p.country_code AS country, CAST(p.ladder_score AS text) AS score, CAST(p.rating_id AS text) AS rating, CASE WHEN p.is_winner THEN '1' ELSE '0' END AS result, CASE WHEN p.is_first_pick THEN '1' ELSE '0' END AS first_pick, p.alive_count, p.leader_pick_slot, bp.banned_unit FROM public.rta_match_participant p INNER JOIN rms ON rms.rid = p.replay_id LEFT JOIN banned_pick bp ON bp.replay_id = p.replay_id AND bp.wizard_id = p.wizard_id ), unit_info AS ( SELECT u.replay_id, u.wizard_id, array_agg(u.unit_master_id::text ORDER BY u.pick_slot_no) AS picked_units, array_agg(u.is_banned ORDER BY u.pick_slot_no) AS unit_banned_flags, array_agg(u.pick_slot_no::int ORDER BY u.pick_slot_no) AS unit_pick_slot_nos, string_agg(u.unit_master_id::text, ',' ORDER BY u.pick_slot_no) AS picked_units_str FROM public.rta_match_unit_pick u INNER JOIN rms ON rms.rid = u.replay_id GROUP BY u.replay_id, u.wizard_id ), pair AS ( SELECT rms.rid, MIN(ui.wizard_id) AS p1w, MAX(ui.wizard_id) AS p2w FROM rms JOIN user_info ui ON ui.replay_id = rms.rid GROUP BY rms.rid ) SELECT rms.rid, rms.battle_type, rms.date_add, CASE WHEN rms.winner_wizard_id = pr.p1w THEN '1' ELSE '2' END AS winner_position, u1.wizard_id AS p1_wizard_id, u1.channel_uid AS p1_channel_uid, u1.wizard_name AS p1_name, u1.country AS p1_country, u1.score AS p1_score, u1.rating AS p1_rating, u1.result AS p1_result, u1.first_pick AS p1_first_pick, u1.alive_count AS p1_alive_count, u1.banned_unit AS p1_banned_unit, u1.leader_pick_slot AS p1_leader_unit, COALESCE(un1.picked_units, ARRAY[]::text[]) AS p1_units, COALESCE(un1.unit_banned_flags, ARRAY[]::boolean[]) AS p1_unit_banned, COALESCE(un1.unit_pick_slot_nos, ARRAY[]::int[]) AS p1_unit_pick_slot_no, COALESCE(un1.picked_units_str, '') AS p1_units_str, u2.wizard_id AS p2_wizard_id, u2.channel_uid AS p2_channel_uid, u2.wizard_name AS p2_name, u2.country AS p2_country, u2.score AS p2_score, u2.rating AS p2_rating, u2.result AS p2_result, u2.first_pick AS p2_first_pick, u2.alive_count AS p2_alive_count, u2.banned_unit AS p2_banned_unit, u2.leader_pick_slot AS p2_leader_unit, COALESCE(un2.picked_units, ARRAY[]::text[]) AS p2_units, COALESCE(un2.unit_banned_flags, ARRAY[]::boolean[]) AS p2_unit_banned, COALESCE(un2.unit_pick_slot_nos, ARRAY[]::int[]) AS p2_unit_pick_slot_no, COALESCE(un2.picked_units_str, '') AS p2_units_str FROM rms JOIN pair pr ON pr.rid = rms.rid JOIN user_info u1 ON u1.replay_id = rms.rid AND u1.wizard_id = pr.p1w JOIN user_info u2 ON u2.replay_id = rms.rid AND u2.wizard_id = pr.p2w LEFT JOIN unit_info un1 ON un1.replay_id = rms.rid AND un1.wizard_id = u1.wizard_id LEFT JOIN unit_info un2 ON un2.replay_id = rms.rid AND un2.wizard_id = u2.wizard_id ORDER BY rms.date_add DESC NULLS LAST

choose.when:
SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND DATE(pp.played_at AT TIME ZONE 'UTC') = CURRENT_DATE
  AND pp.rating_id = #{ratingId}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND DATE(pp.played_at AT TIME ZONE 'UTC') = CURRENT_DATE
  AND pp.rating_id IN
  #{rid}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND pp.played_at >= DATE_TRUNC('week', CURRENT_TIMESTAMP)
  AND pp.rating_id = #{ratingId}

SELECT COUNT(DISTINCT pp.replay_id)::int
FROM public.rta_match_participant pp
WHERE pp.season_id = #{seasonId}
  AND pp.played_at >= DATE_TRUNC('week', CURRENT_TIMESTAMP)
  AND pp.rating_id IN
  #{rid}

mapper.select:
SELECT COALESCE(SUM(t.total_matches), 0)
FROM public.rta_agg_season_rating_match_total t
WHERE t.season_id = #{seasonId}

WITH match_total AS (
SELECT COALESCE(( SELECT t.total_matches FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId} AND t.rating_id = #{ratingId} ), 0) AS total_matches
SELECT COALESCE(SUM(t.total_matches), 0) AS total_matches FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId} AND t.rating_id IN #{rid}
SELECT COALESCE(SUM(t.total_matches), 0) AS total_matches FROM public.rta_agg_season_rating_match_total t WHERE t.season_id = #{seasonId}
), s AS (
SELECT sg.combo_unit_key, sg.pick_cnt, sg.match_cnt, sg.win_cnt, COALESCE(sg.ban_cnt, 0) AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.pick_cnt) AS pick_cnt, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt, SUM(COALESCE(sg.ban_cnt, 0)) AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.pick_cnt) AS pick_cnt, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt, SUM(COALESCE(sg.ban_cnt, 0)) AS ban_cnt FROM public.rta_agg_synergy_solo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT s.combo_unit_key AS monster_id, m.monster_elemental AS monster_elemental, m.kr_name AS monster_name, AS monster_image, s.pick_cnt AS pick_count, ROUND((s.pick_cnt::numeric / NULLIF((SELECT mt.total_matches FROM match_total mt), 0) * 100)::numeric, 2) AS pick_rate, CASE WHEN s.match_cnt > 0 THEN ROUND((s.win_cnt::numeric / s.match_cnt * 100)::numeric, 2) ELSE 0 END AS win_rate, CASE WHEN s.pick_cnt > 0 THEN ROUND((s.ban_cnt::numeric / s.pick_cnt * 100)::numeric, 2) ELSE 0 END AS ban_rate FROM s LEFT JOIN public.monster m ON m.monster_id = s.combo_unit_key WHERE m.kr_name IS NOT NULL AND s.pick_cnt >= #{minPickCount} ORDER BY s.pick_cnt DESC LIMIT #{limit} OFFSET #{offset}

WITH s AS (
SELECT sg.combo_unit_key, sg.match_cnt, sg.win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt FROM public.rta_agg_synergy_duo sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT split_part(s.combo_unit_key, ',', 1) AS monster_id_1, split_part(s.combo_unit_key, ',', 2) AS monster_id_2, m1.kr_name AS monster_name_1, m2.kr_name AS monster_name_2, AS monster_image_1, AS monster_image_2, m1.monster_elemental AS monster_elemental_1, m2.monster_elemental AS monster_elemental_2, s.match_cnt AS match_count, ROUND((s.win_cnt::numeric / NULLIF(s.match_cnt, 0) * 100)::numeric, 2) AS win_rate FROM s LEFT JOIN public.monster m1 ON m1.monster_id = split_part(s.combo_unit_key, ',', 1) LEFT JOIN public.monster m2 ON m2.monster_id = split_part(s.combo_unit_key, ',', 2) WHERE m1.kr_name IS NOT NULL AND m2.kr_name IS NOT NULL AND s.match_cnt >= #{minPickCount} ORDER BY s.match_cnt DESC, (s.win_cnt::numeric / NULLIF(s.match_cnt, 0)) DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}

WITH s AS (
SELECT sg.combo_unit_key, sg.match_cnt, sg.win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id = #{ratingId}
SELECT sg.combo_unit_key, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id IN #{rid} GROUP BY sg.combo_unit_key
SELECT sg.combo_unit_key, SUM(sg.match_cnt) AS match_cnt, SUM(sg.win_cnt) AS win_cnt FROM public.rta_agg_synergy_trio sg WHERE sg.season_id = #{seasonId} AND sg.rating_id > 0 GROUP BY sg.combo_unit_key
) SELECT split_part(s.combo_unit_key, ',', 1) AS monster_id_1, split_part(s.combo_unit_key, ',', 2) AS monster_id_2, split_part(s.combo_unit_key, ',', 3) AS monster_id_3, m1.kr_name AS monster_name_1, m2.kr_name AS monster_name_2, m3.kr_name AS monster_name_3, AS monster_image_1, AS monster_image_2, AS monster_image_3, m1.monster_elemental AS monster_elemental_1, m2.monster_elemental AS monster_elemental_2, m3.monster_elemental AS monster_elemental_3, s.match_cnt AS match_count, ROUND((s.win_cnt::numeric / NULLIF(s.match_cnt, 0) * 100)::numeric, 2) AS win_rate FROM s LEFT JOIN public.monster m1 ON m1.monster_id = split_part(s.combo_unit_key, ',', 1) LEFT JOIN public.monster m2 ON m2.monster_id = split_part(s.combo_unit_key, ',', 2) LEFT JOIN public.monster m3 ON m3.monster_id = split_part(s.combo_unit_key, ',', 3) WHERE m1.kr_name IS NOT NULL AND m2.kr_name IS NOT NULL AND m3.kr_name IS NOT NULL AND s.match_cnt >= #{minPickCount} ORDER BY s.match_cnt DESC, (s.win_cnt::numeric / NULLIF(s.match_cnt, 0)) DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}

/* rta-queries-live.listRtaPlayerWizardNameHistory */ SELECT p.wizard_name, MIN(p.played_at) AS first_seen_at, MAX(p.played_at) AS last_seen_at, COUNT(DISTINCT p.replay_id) AS match_count FROM public.rta_match_participant p WHERE p.wizard_id = #{wizardId} AND p.wizard_name IS NOT NULL AND p.wizard_name <> ''
AND p.season_id = #{seasonId}
GROUP BY p.wizard_name ORDER BY MAX(p.played_at) DESC NULLS LAST, p.wizard_name LIMIT #{limit}

/* rta-queries-live.listRtaPlayerMonsterSnapFromAgg 픽·밴·선첫·승·패·픽률·승률·밴율: 배치 스냅만 사용해 몹 행 간·시즌 fight 정의와 맞물리게 한다. 분모(match_cnt)= rta_agg_summoner_season_fight_snap 우선; 스냅 행 없으면 participant DISTINCT replay( 배치 동일 규약 ). */ WITH match_denom AS (
SELECT #{knownTotalMatches}::numeric AS total_matches
SELECT COALESCE( (SELECT fs.match_cnt::numeric FROM public.rta_agg_summoner_season_fight_snap fs WHERE fs.season_id = #{seasonId} AND fs.wizard_id = #{wizardId}), (SELECT COUNT(DISTINCT mp.replay_id)::numeric FROM public.rta_match_participant mp WHERE mp.season_id = #{seasonId} AND mp.wizard_id = #{wizardId}) ) AS total_matches
), stats_summary AS ( SELECT t.*, /* pick_cnt 는 배치에서 픽+밴 포함 집계(몹 스냅 정의) */ t.pick_cnt AS actual_pick_cnt FROM public.rta_agg_summoner_monster_snap t WHERE t.season_id = #{seasonId} AND t.wizard_id = #{wizardId} ) SELECT s.unit_master_id AS unit_master_id, s.actual_pick_cnt AS actual_pick_cnt, s.pick_cnt AS pick_cnt, s.ban_cnt AS ban_cnt, COALESCE(s.win_cnt, 0) AS win_cnt, COALESCE(s.lose_cnt, 0) AS lose_cnt, s.first_pick_cnt AS first_pick_cnt, m.kr_name AS monster_name, m.monster_elemental AS monster_elemental, AS monster_image, ROUND( (100.0 * s.actual_pick_cnt::numeric / NULLIF(md.total_matches, 0))::numeric, 2 ) AS pick_rate_pct, ROUND( (100.0 * COALESCE(s.first_pick_cnt, 0)::numeric / NULLIF(md.total_matches, 0))::numeric, 2 ) AS first_pick_rate_pct, CASE WHEN COALESCE(s.win_cnt, 0) + COALESCE(s.lose_cnt, 0) > 0 THEN ROUND( (100.0 * COALESCE(s.win_cnt, 0)::numeric / (COALESCE(s.win_cnt, 0) + COALESCE(s.lose_cnt, 0))::numeric)::numeric, 2 ) END AS win_rate_pct, ROUND( (100.0 * COALESCE(s.ban_cnt, 0)::numeric / NULLIF(s.actual_pick_cnt::numeric, 0))::numeric, 2 ) AS ban_rate_pct FROM stats_summary s CROSS JOIN match_denom md LEFT JOIN public.monster m ON m.monster_id = s.unit_master_id::text ORDER BY s.actual_pick_cnt DESC NULLS LAST, s.unit_master_id ASC
LIMIT #{limit}

/* rta-queries-live.listRtaPlayerScoreDailySnap recentTailOnly=true: 최근 N일( snap_date DESC LIMIT )만 읽고 ASC 재정렬 — page-data 초기 로드용 */
SELECT t.snap_date, t.score, t.match_cnt, t.win_cnt, t.lose_cnt, (t.score - LAG(t.score) OVER (ORDER BY t.snap_date))::int AS score_delta FROM ( SELECT d.snap_date, d.end_of_day_score AS score, d.match_cnt, d.win_cnt, d.lose_cnt FROM public.rta_agg_summoner_score_daily_snap d WHERE d.season_id = #{seasonId} AND d.wizard_id = #{wizardId} ORDER BY d.snap_date DESC LIMIT #{limit} ) t ORDER BY t.snap_date ASC
SELECT d.snap_date, d.end_of_day_score AS score, d.match_cnt, d.win_cnt, d.lose_cnt, (d.end_of_day_score - LAG(d.end_of_day_score) OVER (ORDER BY d.snap_date))::int AS score_delta FROM public.rta_agg_summoner_score_daily_snap d WHERE d.season_id = #{seasonId} AND d.wizard_id = #{wizardId} ORDER BY d.snap_date ASC LIMIT #{limit}

/* rta-queries-live.listRtaPlayerMonsterPickSlotMatches */ WITH rms AS MATERIALIZED ( SELECT m.replay_id AS rid, m.played_at AS date_add, m.battle_type, m.winner_wizard_id FROM public.rta_match m INNER JOIN public.rta_match_participant p0 ON p0.replay_id = m.replay_id AND p0.wizard_id = #{wizardId} AND p0.season_id = #{seasonId} AND ( (#{teamSide} = 1 AND p0.is_first_pick IS TRUE) OR (#{teamSide} = 2 AND p0.is_first_pick IS NOT TRUE) ) INNER JOIN public.rta_match_unit_pick up0 ON up0.replay_id = m.replay_id AND up0.wizard_id = p0.wizard_id AND up0.unit_master_id = #{unitMasterId} AND up0.is_banned = false
AND up0.pick_slot_no::int = #{pickSlotNo}::int ORDER BY m.played_at DESC NULLS LAST LIMIT #{limit} OFFSET 0 ), banned_pick AS ( SELECT ub.replay_id, ub.wizard_id, MIN(ub.unit_master_id::text) AS banned_unit FROM public.rta_match_unit_pick ub INNER JOIN rms ON rms.rid = ub.replay_id WHERE ub.is_banned = true GROUP BY ub.replay_id, ub.wizard_id ), user_info AS ( SELECT p.replay_id, p.wizard_id, p.wizard_id::text AS wizard_id_str, p.wizard_name, p.channel_uid, p.country_code AS country, CAST(p.ladder_score AS text) AS score, CAST(p.rating_id AS text) AS rating, CASE WHEN p.is_winner THEN '1' ELSE '0' END AS result, CASE WHEN p.is_first_pick THEN '1' ELSE '0' END AS first_pick, p.alive_count, p.leader_pick_slot, bp.banned_unit FROM public.rta_match_participant p INNER JOIN rms ON rms.rid = p.replay_id LEFT JOIN banned_pick bp ON bp.replay_id = p.replay_id AND bp.wizard_id = p.wizard_id ), unit_info AS ( SELECT u.replay_id, u.wizard_id, array_agg(u.unit_master_id::text ORDER BY u.pick_slot_no) AS picked_units,
array_agg(u.is_banned ORDER BY u.pick_slot_no) AS unit_banned_flags, array_agg(u.pick_slot_no::int ORDER BY u.pick_slot_no) AS unit_pick_slot_nos, string_agg(u.unit_master_id::text, ',' ORDER BY u.pick_slot_no) AS picked_units_str FROM public.rta_match_unit_pick u INNER JOIN rms ON rms.rid = u.replay_id GROUP BY u.replay_id, u.wizard_id ), pair AS ( SELECT rms.rid, MIN(ui.wizard_id) AS p1w, MAX(ui.wizard_id) AS p2w FROM rms JOIN user_info ui ON ui.replay_id = rms.rid GROUP BY rms.rid ) SELECT rms.rid, rms.battle_type, rms.date_add, CASE WHEN rms.winner_wizard_id = pr.p1w THEN '1' ELSE '2' END AS winner_position, u1.wizard_id_str AS p1_wizard_id, u1.channel_uid AS p1_channel_uid, u1.wizard_name AS p1_name, u1.country AS p1_country, u1.score AS p1_score, u1.rating AS p1_rating, u1.result AS p1_result, u1.first_pick AS p1_first_pick, u1.alive_count AS p1_alive_count, u1.banned_unit AS p1_banned_unit, u1.leader_pick_slot AS p1_leader_unit, COALESCE(un1.picked_units, ARRAY[]::text[]) AS p1_units, COALESCE(un1.unit_banned_flags, ARRAY[]::boolean[]) AS p1_unit_banned, COALESCE(un1.unit_pick_slot_nos, ARRAY[]::int[]) AS p1_unit_pick_slot_no, COALESCE(un1.picked_units_str, '') AS p1_units_str, u2.wizard_id_str AS p2_wizard_id, u2.channel_uid AS p2_channel_uid, u2.wizard_name AS p2_name, u2.country AS p2_country, u2.score AS p2_score, u2.rating AS p2_rating, u2.result AS p2_result, u2.first_pick AS p2_first_pick, u2.alive_count AS p2_alive_count, u2.banned_unit AS p2_banned_unit, u2.leader_pick_slot AS p2_leader_unit, COALESCE(un2.picked_units, ARRAY[]::text[]) AS p2_units, COALESCE(un2.unit_banned_flags, ARRAY[]::boolean[]) AS p2_unit_banned, COALESCE(un2.unit_pick_slot_nos, ARRAY[]::int[]) AS p2_unit_pick_slot_no, COALESCE(un2.picked_units_str, '') AS p2_units_str FROM rms JOIN pair pr ON pr.rid = rms.rid JOIN user_info u1 ON u1.replay_id = rms.rid AND u1.wizard_id = pr.p1w JOIN user_info u2 ON u2.replay_id = rms.rid AND u2.wizard_id = pr.p2w LEFT JOIN unit_info un1 ON un1.replay_id = rms.rid AND un1.wizard_id = u1.wizard_id LEFT JOIN unit_info un2 ON un2.replay_id = rms.rid AND un2.wizard_id = u2.wizard_id ORDER BY rms.date_add DESC NULLS LAST

/* rta-queries-live.getRtaMonsterPickSlots */ SELECT ps.team_side, ps.pick_slot_no, ps.pick_cnt, ps.win_cnt, ps.field_cnt, CASE WHEN SUM(ps.pick_cnt) OVER (PARTITION BY ps.team_side) > 0 THEN ROUND(100.0 * ps.pick_cnt / SUM(ps.pick_cnt) OVER (PARTITION BY ps.team_side), 2) END AS pick_share_pct, CASE WHEN ps.pick_cnt > 0 THEN ROUND(100.0 * ps.win_cnt / ps.pick_cnt, 2) END AS win_rate_pct FROM public.rta_agg_monster_pick_slot_snap ps WHERE ps.unit_master_id = #{monsterId} AND ps.season_id = #{seasonId}
AND ps.rating_id = -1 AND ps.rating_id = #{ratingId}
ORDER BY ps.team_side, ps.pick_slot_no
